v1_sql:
SELECT AVG(payment_installments) AS average_installments
FROM order_payments
WHERE payment_type = 'credit_card';

v2_sql:
SELECT AVG(payment_installments) AS avg_installments
FROM order_payments
WHERE payment_type = 'credit_card';

SELECT COUNT(*) AS products_without_category
FROM products
WHERE product_category_name IS NULL OR product_category_name = '';

v1_sql:
SELECT COUNT(*) AS orders_2017
FROM orders
WHERE strftime('%Y', order_purchase_timestamp) = '2017';

v2_sql:
SELECT COUNT(*) AS orders_2017
FROM orders
WHERE strftime('%Y', order_purchase_timestamp) = '2017';

v1_sql:
SELECT COUNT(DISTINCT customer_id) AS unique_customers_in_curitiba
FROM customers
WHERE customer_city = 'Curitiba';

v2_sql:
SELECT COUNT(DISTINCT customer_unique_id) AS unique_customers_in_curitiba
FROM customers
WHERE customer_city = 'curitiba';
